namespace bgiplayer {
void SdlAudioBackend::mix(int16_t* stream, int length) {
    const int frames = length /
        static_cast<int>(sizeof(int16_t) * kChannels);
    std::fill_n(stream, static_cast<std::size_t>(length) /
                           sizeof(int16_t),
                static_cast<int16_t>(0));
    std::scoped_lock lock(mutex_);
    const auto mix_track = [&](Track& slot) {
        if (!slot.active || !slot.clip) {
            return;
        }
        const auto& samples = slot.clip->samples;
        const double frame_count =
            static_cast<double>(samples.size() / kChannels);
        for (int frame = 0; frame < frames; ++frame) {
            if (slot.position >= frame_count) {
                if (slot.bgm) {
                    slot.position = std::fmod(
                        slot.position, frame_count);
                } else {
                    slot.active = false;
                    // Loaded SE media remains available for a later Snd0:24.
                    // One-shots and movie slots are retired by their owners.
                    break;
                }
            }
            const auto source =
                static_cast<std::size_t>(slot.position) * kChannels;
            const int32_t left = static_cast<int32_t>(
                samples[source] * slot.left_gain);
            const int32_t right = static_cast<int32_t>(
                samples[source + 1U] * slot.right_gain);
            const int32_t mixed_left =
                static_cast<int32_t>(stream[frame * 2]) + left;
            const int32_t mixed_right =
                static_cast<int32_t>(stream[frame * 2 + 1]) + right;
            stream[frame * 2] = static_cast<int16_t>(
                std::clamp(mixed_left, -32768, 32767));
            stream[frame * 2 + 1] = static_cast<int16_t>(
                std::clamp(mixed_right, -32768, 32767));
            slot.position += slot.playback_rate;
        }
    };
    for (Track& slot : bgm_tracks_) {
        mix_track(slot);
    }
    for (Track& slot : effect_tracks_) {
        mix_track(slot);
    }
    for (Track& slot : one_shot_tracks_) {
        mix_track(slot);
    }
    for (auto& [key, slot] : movie_tracks_) {
        (void)key;
        mix_track(slot);
    }
}
}  // namespace bgiplayer
